import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.Test;
import static org.junit.Assert.*;
import org.mockito.Mockito;

public class TextNodeTest {

    @Test
    public void constructorTextNodeText() {
        String text = "Hello World!";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void textTextNodeValueReturnsText() {
        String text = "Hello World!";
        TextNode textNode = new TextNode(text);
        assertEquals("Hello World!", textNode.text());
    }

    @Test
    public void textTextNodeValueNormalisesWhitespace() {
        String text = "   Hello   World!  ";
        TextNode textNode = new TextNode(text);
        assertEquals(StringUtil.normaliseWhitespace("   Hello   World!  "), textNode.text());
    }

    @Test
    public void splitTextSplitAtOffsetReturnsNewTextNodeWithTextBeforeOffset() {
        String text = "Hello World!";
        int offset = 6;
        TextNode originalTextNode = new TextNode(text);
        TextNode resultTextNode = originalTextNode.splitText(offset);
        assertEquals("Hello", resultTextNode.text());
    }

    @Test
    public void splitTextSplitAtOffsetReturnsNewTextNodeWithTextAfterOffset() {
        String text = "Hello World!";
        int offset = 0;
        TextNode originalTextNode = new TextNode(text);
        TextNode resultTextNode = originalTextNode.splitText(offset);
        assertEquals("World!", resultTextNode.text());
    }

    @Test
    public void splitTextSplitAtOffsetThrowsInvalidOffsetException() {
        String text = "Hello World!";
        int offset = -1;
        assertThrows(IllegalArgumentException.class, () -> new TextNode(text).splitText(offset));
    }

    @Test
    public void isBlankTextNodeIsBlank() {
        String text = "";
        TextNode textNode = new TextNode(text);
        assertTrue(textNode.isBlank());
    }

    @Test
    public void isBlankTextNodeNotBlank() {
        String text = "Hello World!";
        TextNode textNode = new TextNode(text);
        assertFalse(textNode.isBlank());
    }
}
